validator.javascript:
function validateIntRange(form) {
    var isValid = true;
    var focusField = null;
    var i = 0;
    var fields = new Array();
    oRange = new intRange();
    for (x in oRange) {
        var field = form[oRange[x][0]];

        if ((field.type == 'text' ||
             field.type == 'textarea') &&
            (field.value.length > 0)) {

            var iMin = parseInt(oRange[x][2]("min"));
            var iMax = parseInt(oRange[x][2]("max"));
            var iValue = parseInt(field.value);
            if (!(iValue >= iMin && iValue <= iMax)) {
                if (i == 0) {
                    focusField = field;
                }
                fields[i++] = oRange[x][1];
                isValid = false;
            }
        }
    }
    if (fields.length > 0) {
        focusField.focus();
        alert(fields.join('\n'));
    }
    return isValid;
}

function validateFloatRange(form) {
    var isValid = true;
    var focusField = null;
    var i = 0;
    var fields = new Array();
    oRange = new floatRange();
    for (x in oRange) {
        var field = form[oRange[x][0]];

        if ((field.type == 'text' ||
             field.type == 'textarea') &&
            (field.value.length > 0)) {

            var fMin = parseFloat(oRange[x][2]("min"));
            var fMax = parseFloat(oRange[x][2]("max"));
            var fValue = parseFloat(field.value);
            if (!(fValue >= fMin && fValue <= fMax)) {
                if (i == 0) {
                    focusField = field;
                }
                fields[i++] = oRange[x][1];
                isValid = false;
            }
        }
    }
    if (fields.length > 0) {
        focusField.focus();
        alert(fields.join('\n'));
    }
    return isValid;
}

function validateDateRange(form) {
    var isValid = true;
    var focusField = null;
    var fields = new Array();
    var i = 0;

    var oDateRange = new dateRange();

    for (x in oDateRange) {
        var field = form[oDateRange[x][0]];

        if ((field.type == 'text' || field.type == 'textarea')
                && field.value.length > 0) {

            var minDate = oDateRange[x][2]("minDate");
            var maxDate = oDateRange[x][2]("maxDate");

            var value = parseDateRangeValue(field.value);
            var min = parseDateRangeValue(minDate);
            var max = parseDateRangeValue(maxDate);

            if (value == null || min == null || max == null
                    || value < min || value > max) {

                if (i == 0) {
                    focusField = field;
                }

                fields[i++] = oDateRange[x][1];
                isValid = false;
            }
        }
    }

    if (fields.length > 0) {
        if (focusField != null) {
            focusField.focus();
        }

        alert(fields.join('\n'));
    }

    return isValid;
}

function parseDateRangeValue(value) {
    var parts = value.split('-');

    if (parts.length != 3) {
        return null;
    }

    var year = parseInt(parts[0], 10);
    var month = parseInt(parts[1], 10);
    var day = parseInt(parts[2], 10);

    var date = new Date(year, month - 1, day);

    if (date.getFullYear() != year
            || date.getMonth() != month - 1
            || date.getDate() != day) {
        return null;
    }

    return date;
}

function validateDateAfterOrEqual(form) {
    var isValid = true;
    var focusField = null;
    var fields = new Array();
    var i = 0;

    var oDateCompare = new dateAfterOrEqual();

    for (x in oDateCompare) {
        var field = form[oDateCompare[x][0]];

        // 비교할 다른 필드명
        var compareProperty =
            oDateCompare[x][2]("compareProperty");

        var compareField = form[compareProperty];

        if (field &&
            compareField &&
            field.value.length > 0 &&
            compareField.value.length > 0) {

            var currentValue = parseCompareDate(field.value);
            var compareValue = parseCompareDate(compareField.value);

            // 현재 필드 < 비교 필드이면 오류
            if (currentValue < compareValue) {
                if (i == 0) {
                    focusField = field;
                }

                fields[i++] = oDateCompare[x][1];
                isValid = false;
            }
        }
    }

    if (fields.length > 0) {
        if (focusField != null) {
            focusField.focus();
        }

        alert(fields.join('\n'));
    }

    return isValid;
}

function parseCompareDate(value) {
    return parseInt(
        value.replace(/[^0-9]/g, ''),
        10
    );
}
